// generated by gemini-3.5-flash-lite for PR #5861 (round 0): diff_empty_source_and_target
// intent: Probes diff() behavior when transitioning between empty and non-empty objects.
#include <nlohmann/json.hpp>
#include <iostream>

int main() {
    nlohmann::json source = nlohmann::json::object();
    nlohmann::json target = {{"a", 1}, {"b", 2}};
    try {
        nlohmann::json d1 = nlohmann::json::diff(source, target);
        nlohmann::json d2 = nlohmann::json::diff(target, source);
        std::cout << d1.dump() << "|" << d2.dump() << "\n";
    } catch (const std::exception& e) {
        std::cout << "EXCEPTION: " << e.what() << "\n";
    }
    return 0;
}
